"""specs_s200043.py - Sonnet-w2 family V (generated by mkfamV.py): the four callees record the SEH chain and the object's vtable word; fake outer SEH records 0-2; fs:[0] compared;
flags cover all low bits."""
from pilot import S
from recruits_util import rnd, clear_hooks, hook_rec, seh_record, seh_chain


def _side(c, o):
    sr = seh_record(c, 2)

    def side(emu, k):
        emu.calllog.append(('vt', emu.r32(o)))
        sr(emu, k)
    return side


def _gen(c):
    clear_hooks(c)
    seh_chain(c, c.rng.choice([0, 1, 2]))
    r = c.rng
    o = rnd(c, 0x80)
    hook_rec(c, 0x4dbb00, 1, ret=r.getrandbits(32), pop=4, this=True, side=_side(c, o))
    hook_rec(c, 0x45c3e0, 0, ret=r.getrandbits(32), this=True, side=_side(c, o))
    hook_rec(c, 0x4690b0, 2, ret=r.getrandbits(32), pop=0, side=_side(c, o))
    hook_rec(c, 0x45c510, 1, ret=r.getrandbits(32), pop=0, side=_side(c, o))
    return [o, r.choice([0, 1, 2, 3, 4, 5, 6, 7, 0x100, 0xffffffff, r.getrandbits(32)])]


S(0x447a00, 'GUESS famV 0x447a00', 'thiscall', None, ret='eax', gen=_gen, note='batch200043')
S(0x447ad0, 'GUESS famV 0x447ad0', 'thiscall', None, ret='eax', gen=_gen, note='batch200043')
S(0x447b60, 'GUESS famV 0x447b60', 'thiscall', None, ret='eax', gen=_gen, note='batch200043')
